/**
 * Licences and image credits. The software table is generated by `npm run licenses`
 * (scripts/licenses.mjs); the asset list comes from src/legal/assets.ts. Both are checked by
 * tests/unit/licenses.test.ts.
 */
import type { Lang } from "@/i18n/core";
import { ASSETS } from "../assets";
import thirdParty from "../third-party-licenses.json";
import type { LegalDocFactory } from "../types";

export const LICENSES_VERSION = "2026-10-20";

const NOTICES = "/licenses/THIRD-PARTY-NOTICES.txt";
const INTER = "/licenses/Inter-OFL-1.1.txt";

function repoLink(url: string | null): string {
  if (!url) return "—";
  return `[${url.replace(/^https?:\/\//, "").replace(/^www\./, "")}](${url})`;
}

const installed = thirdParty.filter((p) => p.installed);
const platform = thirdParty.filter((p) => !p.installed);

function softwareRows() {
  return installed.map((p) => [p.name, p.version ?? "—", p.license, repoLink(p.repository)]);
}

const de: LegalDocFactory = (ctx) => ({
  title: "Lizenzen & Bildnachweise",
  intro:
    "FlowPilot AI verwendet ausschließlich lizenzierte Schriften, Symbole und Open-Source-Software. Es gibt keine Stockfotos, keine Fotos von Personen und keine Logos von Kunden oder Partnern. Diese Seite wird aus denselben Daten erzeugt, die unsere automatischen Tests prüfen.",
  sections: [
    {
      id: "schrift",
      title: "Schriftart",
      blocks: [
        `**Inter** (The Inter Project Authors) unter der SIL Open Font License 1.1 – eingebunden über das npm-Paket @fontsource-variable/inter und von unserem eigenen Server ausgeliefert. Es findet keine Anfrage an Google Fonts oder andere Schriftdienste statt. [Lizenztext](${INTER})`,
      ],
    },
    {
      id: "symbole",
      title: "Symbole",
      blocks: ["Symbole von **Lucide** (lucide-react, Lucide Contributors) unter der ISC-Lizenz. Der Lizenztext ist in den [Hinweisen zu Drittsoftware](" + NOTICES + ") enthalten."],
    },
    {
      id: "bilder",
      title: "Bilder und Grafiken",
      blocks: [
        "Alle Grafiken der Website – Logo, Favicon, Produktillustrationen und Diagramme – sind im Projekt selbst erstellt und werden aus Code erzeugt. Die Demo-Dokumente (PDF) werden zur Laufzeit mit synthetischen Daten erzeugt.",
        {
          table: {
            head: ["Quelle", "Art", "Urheber", "Lizenz"],
            rows: ASSETS.map((a) => [a.source, a.kind[ctx.lang], a.author[ctx.lang], a.licence[ctx.lang]]),
            mono: true,
          },
        },
      ],
    },
    {
      id: "pdf",
      title: "PDF-Darstellung",
      blocks: [
        "PDF-Dateien werden mit **PDF.js** (Mozilla Foundation und Mitwirkende, Apache License 2.0) gelesen und angezeigt. PDF.js ist im npm-Paket unpdf (MIT-Lizenz) enthalten. Synthetische PDFs erzeugen wir mit pdf-lib (MIT-Lizenz).",
      ],
    },
    {
      id: "software",
      title: "Open-Source-Software",
      blocks: [
        `Die folgenden ${installed.length} Pakete werden bei einer Produktionsinstallation (npm ci --omit=dev) installiert, einschließlich optionaler Pakete. Die vollständigen Lizenztexte stehen in den [Hinweisen zu Drittsoftware](${NOTICES}). Die Liste wird mit „npm run licenses“ aus package-lock.json erzeugt; ein Test schlägt fehl, wenn ein Paket fehlt oder eine nicht freigegebene Lizenz hinzukommt.`,
        {
          table: {
            head: ["Paket", "Version", "Lizenz", "Quelle"],
            rows: softwareRows(),
            mono: true,
          },
        },
        ...(platform.length > 0
          ? [
              `Zusätzlich enthält die Abhängigkeitsliste ${platform.length} plattformspezifische, optionale Pakete (z. B. Binärdateien für macOS oder Windows), die nur auf dem jeweiligen Betriebssystem installiert werden: ${platform
                .map((p) => `${p.name} (${p.license})`)
                .join(", ")}.`,
            ]
          : []),
        "Hinweis: Die optionalen Bildverarbeitungs-Binärdateien von sharp enthalten libvips unter der GNU LGPL 3.0. Sie werden von Next.js als optionale Abhängigkeit mitinstalliert. Die Anwendung nutzt die Bildoptimierung nicht (images.unoptimized) und schließt diese Binärdateien aus dem ausgelieferten Standalone-Build aus.",
      ],
    },
  ],
});

const en: LegalDocFactory = (ctx) => ({
  title: "Licences & image credits",
  intro:
    "FlowPilot AI only uses licensed fonts, icons and open-source software. There are no stock photos, no photos of people and no customer or partner logos. This page is generated from the same data our automated tests check.",
  sections: [
    {
      id: "schrift",
      title: "Typeface",
      blocks: [
        `**Inter** (The Inter Project Authors) under the SIL Open Font License 1.1 – included via the npm package @fontsource-variable/inter and served from our own server. No request is made to Google Fonts or other font services. [Licence text](${INTER})`,
      ],
    },
    {
      id: "symbole",
      title: "Icons",
      blocks: ["Icons by **Lucide** (lucide-react, Lucide contributors) under the ISC licence. The licence text is included in the [third-party notices](" + NOTICES + ")."],
    },
    {
      id: "bilder",
      title: "Images and graphics",
      blocks: [
        "All graphics on the website – logo, favicon, product illustrations and charts – were created within the project and are generated from code. The demo documents (PDF) are generated at runtime with synthetic data.",
        {
          table: {
            head: ["Source", "Type", "Author", "Licence"],
            rows: ASSETS.map((a) => [a.source, a.kind[ctx.lang], a.author[ctx.lang], a.licence[ctx.lang]]),
            mono: true,
          },
        },
      ],
    },
    {
      id: "pdf",
      title: "PDF rendering",
      blocks: [
        "PDF files are read and displayed with **PDF.js** (Mozilla Foundation and contributors, Apache License 2.0). PDF.js is included in the npm package unpdf (MIT licence). We generate synthetic PDFs with pdf-lib (MIT licence).",
      ],
    },
    {
      id: "software",
      title: "Open-source software",
      blocks: [
        `The following ${installed.length} packages are installed by a production install (npm ci --omit=dev), including optional packages. The full licence texts are in the [third-party notices](${NOTICES}). The list is generated from package-lock.json with “npm run licenses”; a test fails if a package is missing or a licence that has not been approved is added.`,
        {
          table: {
            head: ["Package", "Version", "Licence", "Source"],
            rows: softwareRows(),
            mono: true,
          },
        },
        ...(platform.length > 0
          ? [
              `In addition, the dependency list contains ${platform.length} platform-specific optional packages (e.g. binaries for macOS or Windows) that are only installed on the respective operating system: ${platform
                .map((p) => `${p.name} (${p.license})`)
                .join(", ")}.`,
            ]
          : []),
        "Note: the optional image-processing binaries of sharp contain libvips under the GNU LGPL 3.0. They are installed by Next.js as an optional dependency. The application does not use image optimisation (images.unoptimized) and excludes these binaries from the shipped standalone build.",
      ],
    },
  ],
});

export const licensesDoc: Record<Lang, LegalDocFactory> = { de, en };
